"""Editorial content for the Black Drink site; rendering helpers live in build-pages.py."""


def add_brand_pages(add, intro, split, section, cards, related, cta, link, product_intro, faq):
    products = intro('The world of Black Drink', 'One signature.<br><em>Many occasions.</em>', 'A dark pour. A black-and-gold signature. A place in the moments you choose to make special. Discover the world of Zubrex Black Drink.', '<div class="pill-nav"><a href="#the-drink">The drink</a><a href="#the-moments">The moments</a><a href="#explore-more">The details</a></div>')
    products += '<div id="the-drink" class="anchor-target">' + split('The signature / 500 ml', 'Distinctive at<br>first glance.', '<p>Black Drink brings an unmistakable visual presence to the table. The dark beverage, clear glass and black-and-gold pack create a composition that feels quietly expressive.</p><p>A non-carbonated water-based beverage, presented in the signature 500 ml format. Open it for a moment of your own, or bring it to a table worth sharing.</p>', 'black-drink-studio-pack', 'Zubrex Black Drink 500 ml pack with a dark beverage splash on white', extra=link('black-drink.html', 'Meet Black Drink', True)) + '</div>'
    products += '<div id="the-moments" class="anchor-target">' + split('Your everyday, considered', 'Make room<br>for the moment.', '<p>A sunlit kitchen. A long lunch. An evening that lasts a little longer than planned. The details you choose give familiar occasions their own character.</p><p>Keep the setting simple: clear glassware, a few natural textures and good company. Let the drink add the finishing detail.</p>', 'friends-picnic-editorial', 'Friends sharing Black Drink on a sunlit terrace', campaign=False, reverse=True, extra=link('rituals.html', 'Enter the journal', True)) + '</div>'
    products += '<div id="explore-more" class="anchor-target">' + section('Three ways to discover', 'Go a little deeper.', content=cards([
        ('The Zubrex difference', 'Explore the visual language, signature pack and small details that make the experience feel considered.', 'benefits.html', 'Explore the difference'),
        ('The science notes', 'A clear introduction to composition, pH, alkalinity and the language around drinks.', 'science.html', 'Read the essentials'),
        ('The art of serving', 'Ideas for glassware, a relaxed table and occasions that feel personal.', 'serving-guide.html', 'Find your serve')])) + '</div>'
    products += cta('Bring Zubrex into your world.', 'Ask about Black Drink for your home, your venue or your next occasion.', 'contact.html?interest=black-drink', 'Enquire about Black Drink')
    add('products.html', 'The World of Black Drink | Zubrex by Holy Elixir', 'Explore the world of Zubrex Black Drink: its signature presentation, serving moments, product details and hospitality.', products, 'Collection')

    black = product_intro('The Zubrex signature / Black Drink', 'Black Drink.<br><em>A distinct presence.</em>', 'A distinctive non-carbonated water-based beverage. Black-and-gold presentation, a striking dark pour, and an invitation to make more of the moment.', link('contact.html?interest=black-drink', 'Enquire about Black Drink'), 'black-drink-studio-pack', 'Zubrex Black Drink pack with a dark beverage splash on white', '01', ['500 ml', 'Non-carbonated beverage'], ['The experience', 'The signature pack', 'Your questions'])
    black += split('The experience', 'A little detail.<br>A lasting impression.', '<p>Some details change the whole setting. A dark pour against clear glass. The glint of a silver lid. A signature pack beside a table set with care.</p><p>Zubrex Black Drink belongs wherever you bring your own sense of occasion: an unhurried lunch, a welcome for your guests or a quiet pause at home.</p>', 'joyful-dining-editorial', 'Friends enjoying a shared meal with Black Drink', campaign=False)
    black += '''<section class="section white"><div class="wrap split"><div class="actual-pack"><img src="assets/images/lifestyle-v2/black-drink-actual.webp" alt="Actual Zubrex Black Drink 500 ml pack with silver pull-tab lid and vertical Black Drink label" width="621" height="1100" loading="lazy"></div><div class="split-copy"><p class="eyebrow">A closer look at the pack</p><h2>The signature.<br>In every detail.</h2><p>Black, gold and silver. A vertical wordmark. A recognisable silhouette. The Zubrex pack brings the same sense of occasion to the counter as it does to the table.</p><dl class="spec-list"><div><dt>The drink</dt><dd>Zubrex Black Drink</dd></div><div><dt>The category</dt><dd>Non-carbonated water-based beverage</dd></div><div><dt>The format shown</dt><dd>500 ml</dd></div><div><dt>The full details</dt><dd><a href="contact.html?interest=black-drink">Request the current label</a> for composition, nutrition and storage directions.</dd></div></dl><a class="arrow-link" href="reading-labels.html">Explore the pack notes <span aria-hidden="true">→</span></a></div></div></section>'''
    black += section('A few useful details', 'Before the first sip.', content=faq([
        ('What is Black Drink?', '<p>Zubrex Black Drink is a non-carbonated water-based beverage. The supplied signature pack shows a net quantity of 500 ml.</p>'),
        ('How should I serve it?', '<p>A clean, clear glass makes the dark pour part of the occasion. Choose the setting that suits you and follow the current pack’s storage and serving directions. Explore our <a href="serving-guide.html">serving notes</a> for more ideas.</p>'),
        ('Where can I check the product details?', '<p>Read the current pack for composition, nutrition and use instructions, or <a href="contact.html?interest=black-drink">ask our team</a> for a clear label image before ordering.</p>'),
        ('Can I enquire for a venue or event?', '<p>Yes. Share your venue, city, guest count and date. The team will discuss current availability, quantities and commercial terms with you.</p>')]))
    black += related([
        ('The Zubrex difference', 'The details behind a distinctive presence.', 'benefits.html', 'Discover the difference'),
        ('The science notes', 'Clear explanations of composition and common product terms.', 'science.html', 'Read the essentials'),
        ('For your venue', 'Make Black Drink part of your guest experience.', 'hospitality.html', 'Explore hospitality')])
    black += cta('Your next Zubrex moment.', 'Ask about Black Drink availability for you, your guests or your business.', 'contact.html?interest=black-drink', 'Make an enquiry')
    add('black-drink.html', 'Black Drink | Zubrex by Holy Elixir', 'Discover Zubrex Black Drink, its signature 500 ml pack, distinctive presentation, serving ideas and product details.', black, 'Collection')

    about = intro('Our perspective', 'The beauty is<br><em>in the details.</em>', 'Zubrex by Holy Elixir is an invitation to bring a little more intention to familiar moments. Our focus is Black Drink, and the world you create around it.')
    about += split('A considered point of view', 'Everyday moments.<br>A distinctive signature.', '<p>Premium is a feeling created by the whole experience: what you see, how you serve and the care you bring to the occasion. With Black Drink, the contrast of a dark pour and a light setting becomes the starting point.</p><p>We favour clear glass, natural light, generous space and tables that invite conversation. The setting can be simple. The moment can still feel special.</p>', 'friends-picnic-editorial', 'Friends sharing Black Drink in a bright outdoor setting', campaign=False, extra=link('benefits.html', 'The Zubrex difference', True))
    about += section('The way we see it', 'Considered, from every angle.', content=cards([
        ('A signature worth seeing', 'A black-and-gold pack and a distinctive dark pour give Black Drink its visual identity.', 'black-drink.html', 'Discover the drink'),
        ('A moment worth making', 'A well-chosen glass, a beautiful table and a little time turn a routine pause into a personal ritual.', 'rituals.html', 'Explore the journal'),
        ('A conversation worth having', 'For your home, your venue or your business, the Holy Elixir team is your direct point of contact.', 'contact.html', 'Speak with the team')]))
    about += cta('Make it part of your world.', 'Discover Black Drink for your next table, gathering or guest experience.', 'products.html', 'Explore Black Drink')
    add('about.html', 'Our Perspective | Zubrex by Holy Elixir', 'The Zubrex perspective: distinctive Black Drink, considered presentation and everyday moments made special.', about)

    rituals = intro('The Zubrex journal', 'A sense of<br><em>occasion.</em>', 'Stories of style, serving and the small rituals that give everyday life its own signature.', '<div class="pill-nav"><a href="#visual-signature">The visual signature</a><a href="#at-the-table">At the table</a><a href="#a-change-of-scene">Outside moments</a></div>')
    rituals += '<div id="visual-signature" class="anchor-target">' + split('01 / The visual signature', 'The camera<br>loves contrast.', '<p>A dark drink in a clear glass has a graphic quality all its own. Against pale stone, linen or a sunlit background, the contrast becomes the detail that catches the eye.</p><p>For your own table or a photograph of the occasion, leave room around the glass. A natural backdrop and a single considered detail are often all you need.</p>', 'black-pour-editorial', 'Black Drink and its signature pack with clear glassware on a light table', campaign=False, extra=link('benefits.html', 'Explore the design story', True)) + '</div>'
    rituals += '<div id="at-the-table" class="anchor-target">' + split('02 / At the table', 'Good company<br>sets the scene.', '<p>A long lunch does not need a complicated setting. Set out comfortable glassware, make room for shared plates and let the conversation set the pace.</p><p>Bring Black Drink to the table as a detail in the gathering. Serve it in the way that suits the moment, with the pack nearby for anyone who wants a closer look.</p>', 'joyful-dining-editorial', 'Friends sharing Black Drink over a relaxed meal', campaign=False, reverse=True, extra=link('serving-guide.html', 'Read the serving notes', True)) + '</div>'
    rituals += '<div id="a-change-of-scene" class="anchor-target">' + split('03 / A change of scene', 'An open afternoon.<br>A fresh perspective.', '<p>A courtyard, a terrace, a spot in the shade. Taking a familiar moment outside can give it a completely different feel.</p><p>Bring clean glasses, a simple arrangement and a little time. Follow the pack’s storage directions while travelling and take used packaging with you.</p>', 'movement-break-editorial', 'Two adults sharing Black Drink in a bright architectural courtyard', campaign=False, extra=link('products.html', 'Find your Zubrex moment', True)) + '</div>'
    rituals += related([
        ('A simple serve', 'Glassware, light and a table that feels like you.', 'serving-guide.html', 'Explore serving'),
        ('The essentials', 'Composition and product language, explained simply.', 'science.html', 'The science notes'),
        ('A larger occasion', 'Bring your hospitality plans into the conversation.', 'hospitality.html', 'For your guests')])
    add('rituals.html', 'The Journal | Zubrex by Holy Elixir', 'Explore the Zubrex journal: Black Drink, modern drink culture, visual style, thoughtful tables and outdoor moments.', rituals)

    serving = intro('The journal / Serving notes', 'The art of<br><em>a simple serve.</em>', 'Good glassware. A considered setting. A moment made your own. A few ideas for bringing Black Drink to the table.', '<p class="reading-time">A 3-minute read · Hosting & everyday moments</p>')
    serving += split('Begin with the glass', 'Let the pour<br>take the spotlight.', '<p>Clear glassware shows the dark colour beautifully. Choose a glass that feels comfortable in the hand and has enough room for the way you like to serve.</p><p>On a pale table, a simple tumbler feels graphic and modern. At dinner, match the glass to your place setting and keep the rest of the arrangement relaxed.</p>', 'black-pour-editorial', 'Black Drink with clear glassware on a bright table', campaign=False)
    serving += section('Four considered details', 'Your table, your way.', content='<ol class="editorial-list"><li><h3>Start with a little space.</h3><p>Leave breathing room between glasses, plates and the centre of the table. White linen, pale stone or natural wood give the dark pour room to stand out.</p></li><li><h3>Make it feel personal.</h3><p>A leafy stem, a cloth napkin, your favourite playlist. Choose one or two details you enjoy.</p></li><li><h3>Pour with care.</h3><p>Use clean glasses, check the seal and date, and follow the current pack’s storage and after-opening directions. Keep the label available for guests.</p></li><li><h3>Think about the whole occasion.</h3><p>For a dinner or event, plan your guest count, serving format and timing. Ask the team about current quantities and availability before the day arrives.</p></li></ol>')
    serving += related([
        ('The signature pack', 'Take a closer look at Black Drink.', 'black-drink.html#product-details', 'View the pack'),
        ('For your next event', 'Plan a guest experience with Zubrex.', 'hospitality.html', 'Explore hospitality'),
        ('More everyday moments', 'Light, style and a little inspiration.', 'rituals.html', 'Enter the journal')]) + cta()
    add('serving-guide.html', 'The Serving Notes | Zubrex by Holy Elixir', 'Black Drink serving inspiration: clear glassware, considered presentation, relaxed hosting and a practical occasion checklist.', serving, 'Guides')

    labels = intro('The product notes / The pack', 'Good details.<br><em>Clearly presented.</em>', 'A considered choice starts with knowing what is in your hand. Find the information on your Black Drink pack at a glance.', '<p class="reading-time">A 2-minute read · The product essentials</p>')
    labels += section('The pack, explained', 'Six details in focus.', content=cards([
        ('The identity', 'Look for the Zubrex Black Drink name and the declared beverage category.', '', ''),
        ('Composition & nutrition', 'The current ingredient list and nutritional declaration carry the product-specific details.', '', ''),
        ('The format', 'Check the declared volume and number of packs in the offer. The supplied signature format is 500 ml.', '', ''),
        ('Batch & date', 'The batch identification and date markings help identify the pack and its intended use period.', '', ''),
        ('Storage & serving', 'Follow the current pack’s storage, serving and after-opening directions.', '', ''),
        ('Your point of contact', 'Manufacturer and contact details are printed on the pack. Keep the batch details if you need product support.', '', '')], 'cards--three'))
    labels += section('A closer look', 'The current label, on request.', 'For a specific composition or nutrition question, ask for a clear image of the current label before ordering.', cards([
        ('See the signature pack', 'Explore the actual supplied pack photograph and its design details.', 'black-drink.html#product-details', 'View the pack'),
        ('Ask the team', 'Tell us the exact detail you would like to check. For an existing pack, include its batch reference.', 'contact.html?interest=black-drink', 'Request product information')]))
    labels += related([
        ('The science notes', 'Understand product terms in context.', 'science.html', 'Read the essentials'),
        ('The Zubrex difference', 'A closer look at the product experience.', 'benefits.html', 'Discover the difference'),
        ('Common questions', 'Useful answers about availability and enquiries.', 'faq.html', 'Explore the FAQ')])
    add('reading-labels.html', 'The Pack Notes | Zubrex by Holy Elixir', 'A concise guide to the Zubrex Black Drink pack: identity, composition, quantity, dates, storage and contact information.', labels, 'Guides')

    guide = intro('The Zubrex difference', 'A signature<br><em>all its own.</em>', 'The dark pour. The black-and-gold pack. The thoughtful setting. Discover the details that give Black Drink its distinctive presence.')
    guide += split('01 / Visual character', 'A study<br>in contrast.', '<p>Black Drink brings depth to a light setting. In clear glass, the dark pour feels sculptural; beside white linen or pale stone, it becomes a natural focal point.</p><p>The signature pack continues the story in black, gold and silver. A recognisable wordmark and vertical label create an identity designed to be seen.</p>', 'black-drink-studio-pack', 'Black Drink signature pack and a beverage splash on white', extra=link('black-drink.html#product-details', 'Explore the signature pack', True))
    guide += section('02 / The experience', 'Premium, in the small things.', content=cards([
        ('A distinctive presentation', 'A dark beverage and a signature pack bring a particular character to the counter, the table and the occasion.', '', ''),
        ('A non-carbonated format', 'Black Drink is a non-carbonated water-based beverage. Choose your glassware and serve according to the current pack directions.', '', ''),
        ('A personal ritual', 'A quiet moment at home, a shared lunch or a welcome for guests. The setting is yours to create.', '', '')]))
    guide += split('03 / A place in your day', 'The occasion<br>is what you make it.', '<p>A beautifully considered drink experience need not be elaborate. Natural light, a favourite glass and a little time can change the way an everyday pause feels.</p><p>For restaurants, hotels and events, that same attention to the details becomes part of the welcome.</p>', 'friends-picnic-editorial', 'A relaxed outdoor gathering with Black Drink', campaign=False, reverse=True, extra=link('hospitality.html', 'Bring it to your venue', True))
    guide += related([
        ('The science notes', 'Composition and product language, made clear.', 'science.html', 'Explore the details'),
        ('The journal', 'A little inspiration for your next occasion.', 'rituals.html', 'Read the journal'),
        ('The serving notes', 'Turn a simple pour into a considered moment.', 'serving-guide.html', 'Find your serve')]) + cta('Discover your next favourite detail.', 'Ask about Black Drink availability and make it part of your occasion.', 'contact.html?interest=black-drink', 'Enquire about Black Drink')
    add('benefits.html', 'The Zubrex Difference | Zubrex by Holy Elixir', 'Discover the Zubrex Black Drink experience: signature design, a distinctive dark pour and considered serving moments.', guide, 'Guides')

    science = intro('The science notes', 'A little science.<br><em>A clearer picture.</em>', 'Composition, pH, alkalinity and ionization describe different things. A short guide to the language around water-based drinks.', '<p class="reading-time">A 2-minute read · The essentials</p>')
    science += section('Composition & character', 'There is detail in the composition.', 'The type and concentration of dissolved minerals can influence taste. The full formulation and the amounts present matter; colour alone does not reveal a drink’s composition.', cards([
        ('What is included', 'An ingredient declaration identifies the substances used in a particular product. Read the complete current list for the product in your hand.', '', ''),
        ('How much is present', 'A quantity needs a unit and a reference volume. Figures per 100 ml and per serving describe different amounts.', '', ''),
        ('The whole picture', 'An ingredient name, appearance or single measurement is only one part of a product’s description. Read the details together.', '', '')]))
    science += section('Three terms, clearly explained', 'Different properties.<br>Different meanings.', content='<div class="science-notes"><article><span class="science-notes__mark" aria-hidden="true">pH</span><div><h3>Acidity & basicity</h3><p>pH describes how acidic or basic an aqueous solution is. A pH value is a measurement of that property.</p></div></article><article><span class="science-notes__mark" aria-hidden="true">A</span><div><h3>Alkalinity</h3><p>Alkalinity describes the capacity of a solution to neutralize added acid. It is a different measurement from pH.</p></div></article><article><span class="science-notes__mark" aria-hidden="true">±</span><div><h3>Ionization</h3><p>Ionization is the formation of electrically charged atoms or molecules, called ions. The term describes a chemical process.</p></div></article></div><p class="science-context">These are general explanations of the terms. The current Black Drink label is the place to check its product declarations.</p>')
    science += section('Everyday perspective', 'Keep the routine simple.', 'Fluid needs vary with activity, climate and individual circumstances. Make room for regular drink breaks as part of your day.', cards([
        ('At your own pace', 'An unhurried pause can be a small part of a well-considered day. Explore moments at home and around the table.', 'rituals.html', 'Visit the journal'),
        ('The details you need', 'For a question about Black Drink’s composition or nutritional information, request the current label from the team.', 'reading-labels.html', 'Explore the pack notes')]))
    science += related([
        ('Meet Black Drink', 'The signature pack and the product experience.', 'black-drink.html', 'Discover the drink'),
        ('The Zubrex difference', 'Presentation and the sense of occasion.', 'benefits.html', 'Explore the difference'),
        ('Your question', 'Ask for a specific current product detail.', 'contact.html?interest=black-drink', 'Speak with the team')])
    add('science.html', 'The Science Notes | Zubrex by Holy Elixir', 'A concise guide to composition, pH, alkalinity and ionization, with a practical perspective on the current Black Drink label.', science, 'Guides')

    faqs = [('Black Drink', [
        ('What is Zubrex Black Drink?', '<p>Zubrex Black Drink is a non-carbonated water-based beverage. The supplied signature pack shows a 500 ml net quantity. Visit <a href="black-drink.html">Black Drink</a> for the product story and actual pack.</p>'),
        ('What makes the presentation distinctive?', '<p>A dark pour, black-and-gold pack and silver pull-tab lid form the Zubrex signature. Discover the <a href="benefits.html">design and experience</a> behind it.</p>'),
        ('Where can I check composition and nutrition?', '<p>Read the current product label or <a href="contact.html?interest=black-drink">request a clear label image</a> from the team before ordering. The <a href="reading-labels.html">pack notes</a> explain where to look.</p>'),
        ('How should I store and serve it?', '<p>Follow the current pack directions, including after opening. Our <a href="serving-guide.html">serving notes</a> offer ideas for glassware, presentation and hosting.</p>')]),
        ('Availability & enquiries', [
        ('Can I order on this website?', '<p>The site helps you discover Black Drink and contact the team. There is no online checkout. Price, availability and order arrangements are confirmed directly before a purchase.</p>'),
        ('Is Black Drink available in my city?', '<p>Share your city or postcode, expected quantity and preferred date in an <a href="contact.html?interest=black-drink">enquiry</a>. The team will confirm current coverage and delivery arrangements.</p>'),
        ('Can I ask for regular supply?', '<p>Yes. Share your location, expected quantity and preferred frequency. Supply schedules and commercial terms are discussed directly with the team.</p>'),
        ('What happens when I use the enquiry form?', '<p>The form prepares a draft in your email app. You review and send the email yourself. You can also write directly to <a href="mailto:Info@holy-elixir.com">Info@holy-elixir.com</a>.</p>')]),
        ('Hospitality & trade', [
        ('Can I enquire for a restaurant, hotel or event?', '<p>Yes. Share your venue, city, date and expected quantity. Explore <a href="hospitality.html">hospitality & events</a> for ideas and an enquiry checklist.</p>'),
        ('How can I discuss retail or distribution?', '<p>Visit <a href="partners.html">trade & partnerships</a> and share your business profile, territory and channels. Coverage and commercial terms are discussed with the team.</p>')])]
    faqpage = intro('Here to help', 'A little clarity.<br><em>All in one place.</em>', 'Useful answers about Black Drink, serving, availability and working with Holy Elixir.', '<div class="pill-nav"><a href="#drink-questions">Black Drink</a><a href="#enquiry-questions">Enquiries</a><a href="#business-questions">Hospitality & trade</a></div>')
    for anchor, (title, questions) in zip(['drink-questions', 'enquiry-questions', 'business-questions'], faqs):
        faqpage += f'<section class="section anchor-target" id="{anchor}"><div class="wrap narrow"><p class="eyebrow">Frequently asked</p><h2>{title}</h2>{faq(questions)}</div></section>'
    faqpage += cta('Still curious?', 'Send us your question and we’ll help you find the current details.', 'contact.html', 'Ask the team')
    add('faq.html', 'Frequently Asked Questions | Zubrex by Holy Elixir', 'Answers about Zubrex Black Drink, serving, product details, availability, hospitality and trade enquiries.', faqpage, 'Guides')

    hospitality = intro('For hospitality & events', 'A memorable<br><em>first impression.</em>', 'A distinctive drink can become a considered detail in the welcome. Bring the Zubrex signature to your restaurant, hotel or next gathering.', link('contact.html?interest=hospitality', 'Make a hospitality enquiry'))
    hospitality += split('The guest experience', 'The detail<br>they notice.', '<p>A clear glass on pale linen. A dark pour beside a thoughtfully chosen menu. The signature pack, presented with care. Black Drink gives your table a visual identity of its own.</p><p>From an intimate dinner to a larger occasion, let your service style shape the presentation. Speak with us about pack formats, quantities and current availability.</p>', 'hospitality-editorial', 'A waiter presenting Zubrex Black Drink at an elegantly set restaurant table', campaign=False)
    hospitality += section('A place for the signature', 'Imagine the setting.', content=cards([
        ('Restaurants & cafés', 'A considered table service, a distinctive menu photograph or a shared occasion. Tell us about your venue and the way you serve.', '', ''),
        ('Hotels & guest experiences', 'From the arrival moment to private dining, bring your guest experience into the conversation. Share locations and intended service points.', '', ''),
        ('Events & celebrations', 'A launch, a celebration, an intimate gathering. Tell us the date, guest count and setting so we can discuss supply arrangements.', '', '')]))
    hospitality += section('Plan the occasion', 'A useful first conversation.', content='<ol class="editorial-list"><li><h3>Your setting</h3><p>The venue, location, type of occasion and the experience you have in mind.</p></li><li><h3>Your service</h3><p>Guest count, expected quantity and whether you plan to serve by the glass or present individual packs.</p></li><li><h3>Your timing</h3><p>The event date or intended start date, and whether you are planning one occasion or ongoing supply.</p></li><li><h3>Your practical details</h3><p>Confirm current labels, prices, lead times and delivery coverage with the team before finalising your plans.</p></li></ol>')
    hospitality += related([
        ('The serving notes', 'Glassware and presentation that feel like your venue.', 'serving-guide.html', 'Read the notes'),
        ('The product story', 'The signature pack and the Black Drink experience.', 'black-drink.html', 'Discover the drink'),
        ('A wider relationship', 'Explore retail, distribution and business supply.', 'partners.html', 'Trade & partnerships')]) + cta('Let’s talk about your guests.', 'Share your venue, city and the occasion you have in mind.', 'contact.html?interest=hospitality', 'Start a conversation')
    add('hospitality.html', 'Hospitality & Events | Zubrex by Holy Elixir', 'Bring Zubrex Black Drink to restaurants, hotels and events: considered presentation, guest experiences and hospitality enquiries.', hospitality, 'Business')

    partners = intro('Trade & partnerships', 'One distinctive drink.<br>A <em>shared opportunity.</em>', 'Explore a commercial relationship centred on Zubrex Black Drink. For retail, hospitality and business supply.', link('contact.html?interest=trade', 'Start a trade conversation'))
    partners += section('Find your path', 'Bring Zubrex to your audience.', content=cards([
        ('Retail & distribution', 'Share your business profile, territory and existing channels. Discuss Black Drink availability and current commercial information with the team.', 'contact.html?interest=trade', 'Make a trade enquiry'),
        ('Hospitality & events', 'For restaurants, hotels and gatherings, build the conversation around your venue and the guest experience.', 'hospitality.html', 'Explore hospitality'),
        ('Workplace & business supply', 'Share your locations, expected quantities and preferred supply frequency. Ask about current coverage and delivery arrangements.', 'contact.html?interest=business', 'Discuss business supply')]))
    partners += split('A distinctive presence', 'A signature<br>for your setting.', '<p>Black Drink’s black-and-gold pack and dark pour create a recognisable presentation, from the shelf to the table. Explore how that visual character can sit within your own setting.</p><p>Our first conversation starts with your customers, your channels and the area you serve. Availability, pricing and commercial arrangements are discussed directly.</p>', 'hospitality-editorial', 'Zubrex Black Drink presented for hospitality service', campaign=False, extra=link('products.html', 'Explore the Black Drink world', True))
    partners += related([
        ('Know the product', 'Discover the signature pack and its details.', 'black-drink.html', 'Meet Black Drink'),
        ('The brand perspective', 'The thinking behind the Zubrex presentation.', 'about.html', 'Our perspective'),
        ('Common questions', 'Useful answers before your first conversation.', 'faq.html', 'Explore the FAQ')]) + cta('Let’s explore the opportunity.', 'Tell us about your business, your market and the way you would like to work together.', 'contact.html?interest=trade', 'Speak with Holy Elixir')
    add('partners.html', 'Trade & Partnerships | Zubrex by Holy Elixir', 'Discuss Zubrex Black Drink retail, distribution, hospitality and business supply with the Holy Elixir team.', partners, 'Business')
